  builder_.add_PROVENANCE(PROVENANCE);
  builder_.add_UPDATED_AT(UPDATED_AT);
  builder_.add_CREATED_AT(CREATED_AT);
  builder_.add_QUERY(QUERY);
  builder_.add_MEMBERS(MEMBERS);
  builder_.add_TAGS(TAGS);
  builder_.add_DESCRIPTION(DESCRIPTION);
  builder_.add_NAME(NAME);
  builder_.add_GROUP_ID(GROUP_ID);
  builder_.add_MEMBERSHIP_MODE(MEMBERSHIP_MODE);
