  auto MEMBERS__ = MEMBERS ? _fbb.CreateVector<::flatbuffers::Offset<EGPMember>>(*MEMBERS) : 0;
  auto CREATED_AT__ = CREATED_AT ? _fbb.CreateString(CREATED_AT) : 0;
